"""Count the words in every .txt file under a notes directory."""
import sys
from pathlib import Path

DEFAULT_DIR = Path(__file__).parent / "notes"


def count_words(notes_dir=DEFAULT_DIR):
    """Return {relative path: word count} for every .txt file under notes_dir."""
    notes_dir = Path(notes_dir)
    counts = {}
    for path in sorted(notes_dir.rglob("*.txt")):
        counts[str(path.relative_to(notes_dir))] = len(path.read_text().split())
    return counts


def main(argv):
    notes_dir = argv[1] if len(argv) > 1 else DEFAULT_DIR
    counts = count_words(notes_dir)
    for name, n in counts.items():
        print(f"{n:8d}  {name}")
    print(f"{sum(counts.values()):8d}  total")


if __name__ == "__main__":
    main(sys.argv)

